import { NextResponse } from 'next/server';
import { getSupabaseServer, requireUser } from '../../../../lib/supabase/server';
export const runtime='nodejs';
async function owner(db,id,user){const {data,error}=await db.from('vendors').select('id').eq('id',id).eq('owner_id',user.id).single();if(error||!data)throw new Error('Vendor not found.')} 
export async function POST(request){try{const u=await requireUser(request),b=await request.json(),db=getSupabaseServer();await owner(db,b.vendor_id,u);if(!b.name?.trim())return NextResponse.json({error:'Menu name is required.'},{status:400});const {data,error}=await db.from('menus').insert({vendor_id:b.vendor_id,name:b.name.trim(),source_text:b.source_text||null,status:'Draft'}).select().single();if(error)throw error;return NextResponse.json({menu:data},{status:201})}catch(e){return NextResponse.json({error:e.message==='Unauthorized'?'Unauthorized.':e.message},{status:e.message==='Unauthorized'?401:400})}}
export async function PATCH(request){try{const u=await requireUser(request),b=await request.json(),db=getSupabaseServer();const {data:m,error:me}=await db.from('menus').select('id,vendor_id').eq('id',b.menu_id).single();if(me||!m)throw new Error('Menu not found.');await owner(db,m.vendor_id,u);const patch={};if(b.name!==undefined)patch.name=b.name;if(b.status!==undefined){if(!['Draft','Published','Archived'].includes(b.status))throw new Error('Invalid menu status.');patch.status=b.status}const {data,error}=await db.from('menus').update(patch).eq('id',m.id).select().single();if(error)throw error;return NextResponse.json({menu:data})}catch(e){return NextResponse.json({error:e.message==='Unauthorized'?'Unauthorized.':e.message},{status:e.message==='Unauthorized'?401:400})}}
